function getClassExamBatches(classId){const batches=db.examBatches.filter(b=>String(b.classId)===String(classId));const grouped=new Map();for(const e of db.exams){if(e.batchId)continue;const student=db.students.find(s=>s.id===e.studentId);if(!student||String(student.classId)!==String(classId))continue;const key=[e.title,e.date,e.total].join('|');if(!grouped.has(key))grouped.set(key,{id:'legacy:'+key,classId:String(classId),title:e.title,date:e.date,total:e.total,legacyKey:key});}return batches.concat([...grouped.values()]).sort((a,b)=>b.date.localeCompare(a.date))}
