function renderExamHistory(){const id=$('#exam-history-select').value,batch=getClassExamBatches($('#exam-class-select').value).find(b=>b.id===id);if(!batch){$('#exam-history-table').innerHTML='<div class="profile-empty">اختار امتحان.</div>';return}const students=db.students.filter(s=>String(s.classId)===String(batch.classId)).sort((a,b)=>a.name.localeCompare(b.name,'ar'));const grades=students.map(s=>{const g=db.exams.find(e=>batch.legacyKey?(!e.batchId&&e.studentId===s.id&&[e.title,e.date,e.total].join('|')===batch.legacyKey):(e.batchId===batch.id&&e.studentId===s.id));return `<div class="exam-result-row"><button type="button" class="student-profile-shortcut" data-profile-student="${esc(s.id)}">${esc(s.name)}</button><span>${g?`${esc(String(g.score))} من ${esc(String(g.total))}`:'—'}</span></div>`}).join('');$('#exam-history-table').innerHTML=`<div class="exam-history-head"><strong>${esc(batch.title)}</strong><span>${esc(prettyDate(batch.date))} · الدرجة النهائية ${esc(String(batch.total))}</span></div>${grades||'<div class="profile-empty">لا يوجد طلاب في الصف.</div>'}`}
