function upsertBatchGrade(studentId,score){const batch=db.examBatches.find(b=>b.id===currentBatchId);if(!batch)return;let row=db.exams.find(e=>e.batchId===batch.id&&e.studentId===studentId);if(row)Object.assign(row,{score,total:batch.total,title:batch.title,date:batch.date,classId:batch.classId});else db.exams.push({id:crypto.randomUUID?.()||String(Date.now())+'-'+studentId,studentId,score,total:batch.total,title:batch.title,date:batch.date,classId:batch.classId,batchId:batch.id});save();renderProfileRecords()}
