function renderManualExamStudents(){const students=currentClassStudents();$('#manual-exam-students').innerHTML=students.length?students.map(s=>`<div class="manual-exam-student-row"><button type="button" class="manual-exam-student" data-manual-student="${esc(s.id)}"><span>${esc(s.name)}</span><small>${db.exams.some(e=>e.batchId===currentBatchId&&e.studentId===s.id)?'اتسجلت درجته':'لسه ما اتسجلتش'}</small></button><button type="button" class="student-profile-shortcut" data-profile-student="${esc(s.id)}">الملف</button></div>`).join(''):'<div class="profile-empty">مفيش طلاب في الصف ده.</div>';$$('[data-manual-student]').forEach(b=>b.onclick=()=>openManualStudent(b.dataset.manualStudent))}
