function showProfile(id){const s=db.students.find(x=>x.id===id);if(!s)return;activeProfileId=id;$('#profile-name').textContent=s.name;$('#profile-class').textContent=CLASSES[+s.classId]||'';$('#profile-class-fact').textContent=CLASSES[+s.classId]||'—';$('#profile-phone').textContent=s.phone||'—';$('#profile-guardian').textContent=s.guardianPhone||'—';const schedules=db.schedules.filter(x=>String(x.classId)===String(s.classId)).sort((a,b)=>Number(a.day)-Number(b.day)||a.time.localeCompare(b.time));$('#profile-schedule').textContent=schedules.length?schedules.map(x=>WEEKDAYS[Number(x.day)]+' '+x.time).join('، '):'لم يتم تحديد ميعاد';$('#profile-participation').value=s.participationScore==null?'':String(s.participationScore);$('#profile-respect').value=s.respectScore==null?'':String(s.respectScore);renderStudentPhoto(s);renderProfileRecords();renderStudentAnswers();$('#profile-dialog').showModal()}
